package com.mediconnect.prescription.api; import java.util.UUID; import com.mediconnect.prescription.application.PrescriptionService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/appointments/{appointmentId}/prescriptions") @Tag(name="Prescriptions") @SecurityRequirement(name="bearerAuth") public class PrescriptionController { private final PrescriptionService service; public PrescriptionController(PrescriptionService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Create and validate prescription",description="DOCTOR-only. Medication names are validated through OpenFDA with a Resilience4j circuit breaker and graceful manual-validation fallback.") public PrescriptionResponse create(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID appointmentId,@Valid @RequestBody CreatePrescriptionRequest request){return service.create(jwt.getSubject(),appointmentId,request);} }
